import re, os

cited = set()
for f in os.listdir('.'):
    if f.endswith('.tex'):
        with open(f) as fh:
            text = fh.read()
            for m in re.finditer(r'\\cite[tp]?\{([^}]+)\}', text):
                for key in m.group(1).split(','):
                    cited.add(key.strip())

defined = set()
with open('references.bib') as fh:
    for m in re.finditer(r'@\w+\{(\S+),', fh.read()):
        defined.add(m.group(1))

print(f'Total cited: {len(cited)}')
print(f'Total defined: {len(defined)}')
print()
missing = cited - defined
if missing:
    print('Cited but NOT in bib:')
    for k in sorted(missing):
        print(f'  {k}')
else:
    print('All citations found in bib.')

unused = defined - cited
if unused:
    print()
    print('In bib but NOT cited:')
    for k in sorted(unused):
        print(f'  {k}')
else:
    print('All bib entries are cited.')
